/**
 * An item in Star Citizen, based on EntityClassDefinition XML files.
 */
export interface GameItem {
  /** Unique identifier of the item. */
  uuid?: string;
  /**
     * URL-friendly slug for the item.
     * @nullable
     */
  slug?: string | null;
  /** Display name of the item. */
  name?: string;
  /** Internal class name of the item definition. */
  class_name?: string;
  /** Classification generated by ScDataDumper. */
  classification?: string;
  /**
     * Human-readable label for the item classification
     * @nullable
     */
  classification_label?: string | null;
  /** Item description text, or a translation object with localized strings. */
  description?: string | Translation[] | null;
  /**
     * Item size from AttachDef. Vehicle items range 1-12, FPS items are smaller.
     * @nullable
     */
  size?: number | null;
  /**
     * Physical mass in kilograms from SEntityRigidPhysicsControllerParams.
     * @nullable
     */
  mass?: number | null;
  /**
     * Item rarity from stdItem.Rarity. Only present when the item has rarity data.
     * @nullable
     */
  rarity?: GameItemRarity;
  /** Event or reward source labels for limited/event items. Empty for regular items. */
  event_source?: string[];
  /** Ammo feeder target for ammo-feeder backpacks. Resolves the magazine this item feeds to an item link. Only present for game data >= 4.9.0. */
  ammo_feed?: ItemLink | null;
  /** Whether this item is the base variant (has no parent variant). */
  is_base_variant?: boolean;
  /** Whether this item can be crafted via blueprints. */
  is_craftable?: boolean;
  /** Whether this item can be generated as loot. */
  is_lootable?: boolean;
  /**
     * Crafting blueprints that produce this item. Only returned when the item is craftable. Use include=blueprints to get full blueprint data instead of links.
     * @nullable
     */
  blueprint?: (ItemBlueprintLink | Blueprint)[] | null;
  /**
     * Only returned for Ship.* items (derived formatting for ship grades).
     * @nullable
     */
  grade?: string | null;
  /**
     * Only returned for Ship.* items.
     * @nullable
     */
  class?: string | null;
  /**
     * Key/value pairs derived from the item description.
     * @nullable
     */
  description_data?: ItemDescriptionData[] | null;
  /**
     * Manufacturer name extracted from the description data entries.
     * @nullable
     */
  manufacturer_description?: string | null;
  manufacturer?: ManufacturerLink | null;
  /**
     * Item type identifier (NOITEM_ prefix removed), e.g. Weapon, Armor, Clothing.
     * @nullable
     */
  type?: string | null;
  /**
     * Human-readable label for the item type
     * @nullable
     */
  type_label?: string | null;
  /**
     * Web URL for filtering items by type
     * @nullable
     */
  type_web_url?: string | null;
  /**
     * Item sub-type identifier, e.g. Small, Medium, Rocket.
     * @nullable
     */
  sub_type?: string | null;
  /**
     * Human-readable label for the item sub-type
     * @nullable
     */
  sub_type_label?: string | null;
  /**
     * Only returned for WeaponAttachment items (non-placeholder). Maps sub_type to a display slot name.
     * @nullable
     */
  position?: string | null;
  /**
     * Only returned for turret-like items.
     * @nullable
     */
  max_mounts?: number | null;
  /**
     * Only returned for MissileLauncher turret-like items.
     * @nullable
     */
  max_missiles?: number | null;
  /**
     * Only returned for BombLauncher turret-like items.
     * @nullable
     */
  max_bombs?: number | null;
  /**
     * Only returned for turret-like items.
     * @nullable
     */
  min_size?: number | null;
  /**
     * Only returned for turret-like items.
     * @nullable
     */
  max_size?: number | null;
  dimension?: ItemDimension;
  inventory?: ItemInventory | null;
  /**
     * Item tags from AttachDef.
     * @nullable
     */
  tags?: string[] | null;
  /**
     * Required tags an item must match to attach.
     * @nullable
     */
  required_tags?: string[] | null;
  /**
     * Entity tag UUIDs from the database relationship (empty array when not loaded).
     * @nullable
     */
  entity_tags?: string[] | null;
  /**
     * Entity tags from the database relationship (empty array when not loaded).
     * @nullable
     */
  entity_tag_map?: GameItemEntityTagMapItem[] | null;
  /**
     * Generated from SInteractionPointParams
     * @nullable
     */
  interactions?: string[] | null;
  /**
     * Item ports derived from stdItem.Ports.
     * @nullable
     */
  ports?: ItemPort[] | null;
  heat?: ItemHeatConnection | null;
  temperature?: ItemTemperature | null;
  power?: ItemPowerConnection | null;
  distortion?: ItemDistortion | null;
  durability?: ItemDurability | null;
  resource_container?: ResourceContainer | null;
  resource_network?: ResourceNetwork | null;
  emission?: ItemEmission | null;
  seat?: Seat | null;
  ammunition?: Ammunition | null;
  temperature_resistance?: TemperatureResistance | null;
  radiation_resistance?: RadiationResistance | null;
  /**
     * G-force tolerance modifier. Positive values increase tolerance, negative values reduce it. 0 = neutral.
     * @nullable
     */
  gforce_resistance?: number | null;
  armor?: VehicleArmor | null;
  cooler?: Cooler | null;
  flight_controller?: FlightController | null;
  fuel_tank?: FuelTank | null;
  fuel_intake?: FuelIntake | null;
  hacking_chip?: HackingChip | null;
  mining_laser?: MiningLaser | null;
  mining_module?: MiningModule | null;
  mining_modifier?: MiningModifier | null;
  /** Mining gadget currently resolves using the mining_module schema. */
  mining_gadget?: MiningModule | null;
  quantum_drive?: QuantumDrive | null;
  quantum_interdiction_generator?: QuantumInterdictionGenerator | null;
  self_destruct?: SelfDestruct | null;
  shield?: Shield | null;
  shield_controller?: ShieldController | null;
  jump_drive?: JumpDrive | null;
  thruster?: Thruster | null;
  power_plant?: PowerPlant | null;
  radar?: Radar | null;
  cargo_grid?: ItemInventory | null;
  /** Note: FPS armor currently also populates this key due to resource logic. Prefer returning suit_armor instead. */
  clothing?: Clothing | SuitArmor | null;
  /** FPS Armor */
  suit_armor?: SuitArmor | null;
  bomb?: Bomb | null;
  missile?: Missile | null;
  missile_rack?: MissileRack | null;
  counter_measure?: CounterMeasure | null;
  emp?: Emp | null;
  personal_weapon?: PersonalWeapon | null;
  vehicle_weapon?: VehicleWeapon | null;
  melee_weapon?: MeleeWeapon | null;
  grenade?: Grenade | null;
  /** @deprecated */
  knife?: MeleeWeapon | null;
  turret?: Turret | null;
  tractor_beam?: TractorBeam | null;
  food?: Food | null;
  medical?: Medicine | null;
  weapon_rack?: WeaponRack | null;
  weapon_modifier?: WeaponModifier | null;
  iron_sight?: WeaponAttachmentIronSight | null;
  laser_pointer?: WeaponAttachmentLaserPointer | null;
  flashlight?: WeaponAttachmentFlashlight | null;
  magazine?: WeaponAttachmentMagazine | null;
  compensator?: WeaponAttachmentBarrelAttachment | null;
  flash_hider?: WeaponAttachmentBarrelAttachment | null;
  base_variant?: ItemLink | null;
  /** @nullable */
  variants?: ItemLink[] | null;
  /** Only returned when `include=related_items` is requested. */
  related_items?: ItemRelatedItems | null;
  /**
     * Deprecated: shop data is not available in the source files anymore.
     * @deprecated
     * @nullable
     */
  shops?: GameItemShopsItem[] | null;
  /**
     * Images from external sources for this item.
     * @nullable
     */
  images?: GameItemImagesItem[] | null;
  /** Item prices from UEX Corp API. */
  uex_prices?: GameItemUexPrices;
  /**
     * Only returned when `include=vehicles` is requested. Vehicles that have this item installed.
     * @nullable
     */
  vehicles?: VehicleLink[] | null;
  /** Web URL for item detail page */
  web_url?: string;
  /** API URL for item detail endpoint */
  link?: string;
  /** Date/time this item's version-specific data was updated. */
  updated_at?: string;
  /** Game version code */
  version?: string;
}

